"""Supervised localhost whisper.cpp client using in-memory WAV requests."""

from __future__ import annotations

import io
import json
import subprocess
import urllib.error
import urllib.request
import wave
from collections.abc import Callable, Sequence
from urllib.parse import urljoin

from dictate.privacy import PrivacyError, validate_loopback_url


class ASRError(RuntimeError):
	"""A content-free local ASR failure."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
	def redirect_request(self, request: object, fp: object, code: int, msg: str, headers: object, newurl: str) -> None:
		return None


def _wav(pcm: bytes) -> bytes:
	buffer = io.BytesIO()
	with wave.open(buffer, "wb") as output:
		output.setnchannels(1)
		output.setsampwidth(2)
		output.setframerate(16_000)
		output.writeframes(pcm)
	return buffer.getvalue()


class WhisperServer:
	"""Own one local whisper-server process for the lifetime of a service."""

	def __init__(
		self,
		endpoint: str,
		command: Sequence[str] | None = None,
		*,
		popen: Callable[..., subprocess.Popen[bytes]] = subprocess.Popen,
		opener: Callable[..., object] | None = None,
	) -> None:
		validate_loopback_url(endpoint)
		self.endpoint = endpoint.rstrip("/") + "/"
		self._command = tuple(command) if command else None
		self._popen = popen
		self._process: subprocess.Popen[bytes] | None = None
		self._opener = opener or urllib.request.build_opener(_NoRedirect()).open

	def start(self) -> None:
		if self._command is None or self._process is not None:
			return
		try:
			self._process = self._popen(self._command, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
		except OSError as error:
			raise ASRError("local ASR runtime could not start") from error

	def stop(self) -> None:
		if self._process is not None:
			self._process.terminate()
			self._process = None

	def ready(self) -> bool:
		self._ensure_running()
		request = urllib.request.Request(urljoin(self.endpoint, "health"), method="GET")
		try:
			with self._opener(request, timeout=2) as response:
				return 200 <= response.status < 300
		except (urllib.error.URLError, TimeoutError, OSError):
			return False

	def transcribe(self, pcm: bytes, terms: Sequence[str] = ()) -> str:
		if not pcm:
			raise ASRError("audio capture was empty")
		self._ensure_running()
		validate_loopback_url(self.endpoint)
		request = urllib.request.Request(
			urljoin(self.endpoint, "inference"),
			data=_wav(pcm),
			headers={"Content-Type": "audio/wav", "Accept": "application/json", "X-Dictate-Term-Count": str(len(terms))},
			method="POST",
		)
		try:
			with self._opener(request, timeout=30) as response:
				if not 200 <= response.status < 300:
					raise ASRError("local ASR returned an unsuccessful status")
				payload = json.loads(response.read().decode("utf-8"))
		except (urllib.error.URLError, TimeoutError, OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
			raise ASRError("local ASR request failed") from error
		text = payload.get("text") if isinstance(payload, dict) else None
		if not isinstance(text, str) or not text.strip():
			raise ASRError("local ASR returned no usable transcription")
		return text.strip()

	def _ensure_running(self) -> None:
		if self._process is not None and self._process.poll() is not None:
			raise ASRError("local ASR runtime stopped unexpectedly")

"""Default-device, in-memory 16 kHz mono signed-16-bit PCM capture."""

from __future__ import annotations

from collections.abc import Callable
from typing import Protocol


class _InputStream(Protocol):
	def start(self) -> None: ...
	def stop(self) -> None: ...
	def close(self) -> None: ...


class Recorder:
	"""Capture one utterance in RAM; no audio is written to disk."""

	def __init__(self, device: str = "system-default", stream_factory: Callable[..., _InputStream] | None = None) -> None:
		self._device = None if device == "system-default" else device
		self._stream_factory = stream_factory or self._sounddevice_stream
		self._stream: _InputStream | None = None
		self._frames = bytearray()

	@staticmethod
	def _sounddevice_stream(**kwargs: object) -> _InputStream:
		import sounddevice

		return sounddevice.RawInputStream(**kwargs)

	def start(self) -> None:
		if self._stream is not None:
			raise RuntimeError("recording is already active")
		self._frames.clear()
		self._stream = self._stream_factory(
			samplerate=16_000,
			channels=1,
			dtype="int16",
			device=self._device,
			callback=self._on_audio,
		)
		self._stream.start()

	def _on_audio(self, indata: object, frames: int, time_info: object, status: object) -> None:
		if status:
			raise RuntimeError("audio capture reported a device status")
		self._frames.extend(bytes(indata))

	def stop(self) -> bytes:
		stream, self._stream = self._stream, None
		if stream is None:
			raise RuntimeError("recording is not active")
		try:
			stream.stop()
		finally:
			stream.close()
		audio = bytes(self._frames)
		self._frames.clear()
		return audio

	def discard(self) -> None:
		self._frames.clear()

"""Mandatory, deterministic loopback-only Ollama cleanup client."""

from __future__ import annotations

import json
import urllib.error
import urllib.request
from collections.abc import Callable, Sequence
from urllib.parse import urljoin

from dictate.privacy import validate_loopback_url


class CleanupError(RuntimeError):
	"""A content-free local cleanup failure."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
	def redirect_request(self, request: object, fp: object, code: int, msg: str, headers: object, newurl: str) -> None:
		return None


def _prompt(transcript: str, style: str, terms: Sequence[str], context: str | None) -> str:
	term_text = ", ".join(terms) or "(none)"
	context_text = context or "(none)"
	return (
		"Transform the dictated transcript into polished writing. Preserve intended meaning and supplied terms. "
		"Do not answer questions, add facts, explain, reason aloud, or invent content. Return only the transformed text.\n"
		f"Style: {style}\nTerms: {term_text}\nContext: {context_text}\nTranscript: {transcript}"
	)


class OllamaClient:
	def __init__(self, endpoint: str, model: str, *, opener: Callable[..., object] | None = None) -> None:
		validate_loopback_url(endpoint)
		self.endpoint = endpoint.rstrip("/") + "/"
		self.model = model
		self._opener = opener or urllib.request.build_opener(_NoRedirect()).open

	def ready(self) -> bool:
		validate_loopback_url(self.endpoint)
		payload = {"model": self.model, "prompt": "", "stream": False, "keep_alive": "5m", "options": {"temperature": 0, "num_ctx": 2048}, "think": False}
		try:
			self._request(payload)
		except CleanupError:
			return False
		return True

	def clean(self, transcript: str, style: str, terms: Sequence[str] = (), context: str | None = None) -> str:
		if not transcript.strip():
			raise CleanupError("ASR returned no usable transcription")
		payload = {
			"model": self.model,
			"prompt": _prompt(transcript, style, terms, context),
			"stream": False,
			"think": False,
			"keep_alive": "5m",
			"options": {"temperature": 0, "num_ctx": 2048},
		}
		response = self._request(payload)
		text = response.get("response") if isinstance(response, dict) else None
		if not isinstance(text, str) or not text.strip() or response.get("thinking"):
			raise CleanupError("local cleanup returned no usable output")
		return text.strip()

	def _request(self, payload: dict[str, object]) -> dict[str, object]:
		validate_loopback_url(self.endpoint)
		body = json.dumps(payload).encode("utf-8")
		request = urllib.request.Request(
			urljoin(self.endpoint, "api/generate"), data=body, headers={"Content-Type": "application/json", "Accept": "application/json"}, method="POST"
		)
		try:
			with self._opener(request, timeout=30) as response:
				if not 200 <= response.status < 300:
					raise CleanupError("local cleanup returned an unsuccessful status")
				result = json.loads(response.read().decode("utf-8"))
		except (urllib.error.URLError, TimeoutError, OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
			raise CleanupError("local cleanup request failed") from error
		if not isinstance(result, dict):
			raise CleanupError("local cleanup returned an invalid response")
		return result

"""Test-only process guard that rejects non-loopback socket connections."""

from __future__ import annotations

import ipaddress
import socket
from typing import Any


def install_loopback_only_guard() -> None:
    """Install a process-local socket guard for offline acceptance tests."""
    original_connect = socket.socket.connect
    original_connect_ex = socket.socket.connect_ex
    original_create_connection = socket.create_connection

    def allowed(address: object) -> bool:
        if not isinstance(address, tuple) or not address:
            return False
        try:
            return ipaddress.ip_address(address[0]).is_loopback
        except ValueError:
            return address[0] == "localhost"

    def connect(sock: socket.socket, address: object) -> Any:
        if not allowed(address):
            raise OSError("offline acceptance guard blocked non-loopback connection")
        return original_connect(sock, address)

    def connect_ex(sock: socket.socket, address: object) -> int:
        if not allowed(address):
            return 1
        return original_connect_ex(sock, address)

    def create_connection(address: object, *args: object, **kwargs: object) -> socket.socket:
        if not allowed(address):
            raise OSError("offline acceptance guard blocked non-loopback connection")
        return original_create_connection(address, *args, **kwargs)

    socket.socket.connect = connect
    socket.socket.connect_ex = connect_ex
    socket.create_connection = create_connection

"""Generic pynput press/release monitoring and keyboard insertion primitives."""

from __future__ import annotations

from collections.abc import Callable
from typing import Protocol


class _Listener(Protocol):
    def start(self) -> None: ...
    def stop(self) -> None: ...


class PynputHotkey:
    """Emit one press and one release per configured held key."""

    def __init__(self, trigger: str, on_press: Callable[[], None], on_release: Callable[[], None], listener_factory: Callable[..., _Listener] | None = None) -> None:
        self._trigger = trigger
        self._on_press = on_press
        self._on_release = on_release
        self._listener_factory = listener_factory or self._listener
        self._listener_instance: _Listener | None = None
        self._held = False

    @staticmethod
    def _listener(**kwargs: object) -> _Listener:
        from pynput import keyboard

        return keyboard.Listener(**kwargs)

    def start(self) -> None:
        if self._listener_instance is not None:
            return
        self._listener_instance = self._listener_factory(on_press=self._press, on_release=self._release)
        self._listener_instance.start()

    def stop(self) -> None:
        if self._listener_instance is not None:
            self._listener_instance.stop()
            self._listener_instance = None
        self._held = False

    def _matches(self, key: object) -> bool:
        name = getattr(key, "name", None)
        return name == self._trigger or str(key).removeprefix("Key.") == self._trigger

    def _press(self, key: object) -> None:
        if self._matches(key) and not self._held:
            self._held = True
            self._on_press()

    def _release(self, key: object) -> None:
        if self._matches(key) and self._held:
            self._held = False
            self._on_release()


def write_text(text: str, controller_factory: Callable[[], object] | None = None) -> None:
    """Inject text only when a platform adapter has just verified its target."""
    if not text:
        return
    if controller_factory is None:
        from pynput import keyboard

        controller_factory = keyboard.Controller
    controller = controller_factory()
    controller.write(text)

from __future__ import annotations

import unittest

from dictate.config import Preferences
from dictate.platform.base import Capability, PlatformAdapter, TargetSnapshot
from dictate.service import DictationService, RecoveryStore


class FocusPlatform(PlatformAdapter):
    def __init__(self) -> None:
        self.active = TargetSnapshot("app", "A", "field")
        self.writes: list[tuple[str, str]] = []
    def microphone_permission(self) -> Capability: return Capability(True)
    def trigger_permission(self) -> Capability: return Capability(True)
    def placement_permission(self) -> Capability: return Capability(True)
    def context_permission(self) -> Capability: return Capability(False)
    def snapshot_target(self) -> TargetSnapshot | None: return self.active
    def read_context(self, target: TargetSnapshot, limit: int) -> str | None: return None
    def target_matches(self, target: TargetSnapshot) -> bool: return target == self.active
    def insert_text(self, target: TargetSnapshot, text: str) -> bool:
        if target != self.active: return False
        self.writes.append((target.window_id, text)); return True
    def start_hotkey(self, *args: object) -> None: pass
    def stop_hotkey(self) -> None: pass
    def recovery_instruction(self) -> str: return "recover"


class Recorder:
    def start(self) -> None: pass
    def stop(self) -> bytes: return b"pcm"
    def discard(self) -> None: pass
class ASR:
    def start(self) -> None: pass
    def stop(self) -> None: pass
    def transcribe(self, pcm: bytes, terms: tuple[str, ...] = ()) -> str: return "spoken"
class Cleanup:
    def clean(self, transcript: str, style: str, terms: tuple[str, ...] = (), context: object = None) -> str: return "polished"


class FocusSafetyAcceptanceTests(unittest.TestCase):
    def test_focus_change_from_a_to_b_never_writes_to_b_and_requires_recovery(self) -> None:
        platform, recovery = FocusPlatform(), RecoveryStore()
        service = DictationService(Preferences(), platform, Recorder(), ASR(), Cleanup(), recovery=recovery)
        service.press()
        platform.active = TargetSnapshot("app", "B", "field")
        service.release()
        self.assertEqual([], platform.writes)
        self.assertEqual("polished", recovery.take())


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations

import os
import subprocess
import sys
import textwrap
import unittest
from pathlib import Path


class OfflineHarnessAcceptanceTests(unittest.TestCase):
    def test_service_process_blocks_external_socket_and_completes_pipeline(self) -> None:
        script = textwrap.dedent(
            """
            import socket
            from dictate.config import Preferences
            from dictate.offline import install_loopback_only_guard
            from dictate.platform.base import Capability, PlatformAdapter, TargetSnapshot
            from dictate.service import DictationService, RecoveryStore
            install_loopback_only_guard()
            try:
                socket.create_connection(("8.8.8.8", 53), timeout=0.1)
            except OSError:
                pass
            else:
                raise SystemExit("external socket was not blocked")
            class P(PlatformAdapter):
                def microphone_permission(self): return Capability(True)
                def trigger_permission(self): return Capability(True)
                def placement_permission(self): return Capability(True)
                def context_permission(self): return Capability(False)
                def snapshot_target(self): return TargetSnapshot("a", "w", "t")
                def read_context(self, target, limit): return None
                def target_matches(self, target): return True
                def insert_text(self, target, text): self.inserted = True; return True
                def start_hotkey(self, *args): pass
                def stop_hotkey(self): pass
                def recovery_instruction(self): return "recover"
            class R:
                def start(self): pass
                def stop(self): return b"pcm"
                def discard(self): pass
            class A:
                def start(self): pass
                def stop(self): pass
                def transcribe(self, pcm, terms=()): return "spoken"
            class C:
                def clean(self, transcript, style, terms=(), context=None): return "polished"
            platform = P()
            service = DictationService(Preferences(), platform, R(), A(), C(), recovery=RecoveryStore())
            service.press(); service.release()
            if not getattr(platform, "inserted", False): raise SystemExit("pipeline did not insert")
            print("offline-guard-pass")
            """
        )
        source_root = str(Path(__file__).parents[2] / "src")
        environment = os.environ | {"PYTHONPATH": source_root}
        result = subprocess.run([sys.executable, "-c", script], capture_output=True, text=True, env=environment, check=False)
        self.assertEqual(0, result.returncode, result.stderr)
        self.assertEqual("offline-guard-pass\n", result.stdout)


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations
import contextlib import io import unittest
from dictate.cli import main from dictate.service import RecoveryStore
class RecoveryAcceptanceTests(unittest.TestCase): def test_recovery_is_stdout_only_once_and_memory_only(self) -> None: store = RecoveryStore() store.put("final result") stdout, stderr = io.StringIO(), io.StringIO() with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr): self.assertEqual(0, main(["serve", "--recover"], recovery=store)) self.assertEqual(1, main(["serve", "--recover"], recovery=store)) self.assertEqual("final result\n", stdout.getvalue()) self.assertNotIn("final result", stderr.getvalue())
def test_timeout_and_replacement_clear_old_result(self) -> None: now = [0.0] store = RecoveryStore(timeout_seconds=1, clock=lambda: now[0]) store.put("old") store.put("new") self.assertEqual("new", store.take()) store.put("expired") now[0] = 2.0 self.assertIsNone(store.take())
if __name__ == "__main__": unittest.main()
